import json
with open('/home/ubuntu/.agent-ml-research-idea_gen_0513_3/projects/symb_invariant_consensus/logs/workers/worker_exp_alpha-ablation-0-1_20260523T193634.log') as f:
    lines = f.readlines()
# Check stdout results with alpha data
for line in lines:
    try:
        obj = json.loads(line)
        if obj.get('type') == 'user':
            content = obj.get('message', {}).get('content', [])
            for block in content:
                if isinstance(block, dict) and block.get('type') == 'tool_result':
                    c = block.get('content', '')
                    if 'alpha' in c.lower() and ('agree' in c.lower() or '100' in c):
                        # Parse nested JSON
                        try:
                            inner = json.loads(c)
                            result = json.loads(inner.get('result', '{}'))
                            stdout = result.get('data', {}).get('stdout', '')
                            if stdout and len(stdout) > 30:
                                print(stdout[:2000])
                                print('===')
                        except:
                            pass
    except:
        continue
